 out=ROOT/'outputs/r91';out.mkdir(exist_ok=True);pp=ROOT/'outputs/r89/paired_events.parquet';mp=ROOT/'data/r26_mapped_report_events.parquet';cp=ROOT/'data/r26_non_event_context.parquet';p=pd.read_parquet(pp);m=pd.read_parquet(mp);keys=['stock_code','broker','publication_date'];cols=keys+['signal_date','month']+KEY+['security_id','instrument','_merge'];mapped=p[keys+['revision_current','revision_next']].merge(m[cols],on=keys,how='left',validate='one_to_many');assert len(mapped[keys].drop_duplicates())==len(p);mapped.to_parquet(out/'mapped_pairs.parquet',index=False)
 q=mapped[mapped._merge.eq('both')].copy();q['publication_year']=q.publication_date.dt.year;gkeys=KEY+['signal_date','publication_year'];company=q.groupby(gkeys+['security_id']).agg(current=('revision_current','median'),next=('revision_next','median'),brokers=('broker','nunique')).reset_index();company.to_parquet(out/'company_events.parquet',index=False)
 events=company.groupby(gkeys).agg(current=('current','median'),next=('next','median'),companies=('security_id','nunique'),broker_company_pairs=('brokers','sum')).reset_index();context=pd.read_parquet(cp).rename(columns={'date':'signal_date'});events=events.merge(context[KEY+['signal_date','block','pre20','pre60','reaction','post20','post60','entry_date','maturity20','maturity60']],on=KEY+['signal_date'],how='left',validate='many_to_one');events['current_sign']=np.sign(events.current);events['next_sign']=np.sign(events.next);events.to_parquet(out/'industry_events.parquet',index=False)
 dates=[]
