 js(out/'summary.json',summary);js(out/'coverage.json',dict(pairs=len(p),mapped_rows=len(mapped),unmapped_rows=int(mapped._merge.ne('both').sum()),company_events=len(company),industry_events=len(events),industry_opposite=int((events.current_sign*events.next_sign<0).sum()),industry_same=int(events.current_sign.eq(events.next_sign).sum()),industry_one_zero=int(((events.current_sign==0)^(events.next_sign==0)).sum()),known_post20=int(events.post20.notna().sum()),known_post60=int(events.post60.notna().sum()),excluded_on_actual=0));inputs=[pp,mp,cp,ROOT/'protocols/r91.json',Path(__file__)];js(out/'receipt.json',dict(reads={str(x):sha(x) for x in inputs},strict_PIT=False));print((out/'coverage.json').read_text());print(json.dumps([x for x in summary if x['scope']=='pooled' and x['metric']=='post20'],default=str))
